    assign nodone_run_next = (win_run && v_active_i && !v_done_i)
                           ? (nodone_run_q + 64'd1) : 64'd0;
    assign nodone_max_next = (nodone_run_next > nodone_max_q)
                           ? nodone_run_next : nodone_max_q;

