            frozen_q  <= 1'b0;
            aborted_q <= 1'b0;
            err_q     <= 64'd0;

            mode_q     <= DEF_MODE;
            window_q   <= DEF_WINDOW;
            target_q   <= DEF_TARGET;
            deadband_q <= DEF_DEADBAND;
            initbud_q  <= DEF_INITBUD;
            minbud_q   <= DEF_MINBUD;
            maxbud_q   <= DEF_MAXBUD;
            step_q     <= DEF_STEP;
            cap_q      <= DEF_CAP;
            whit_q     <= DEF_WHIT;
            wmiss_q    <= DEF_WMISS;
            wptw_q     <= DEF_WPTW;

            balance_q   <= $signed({32'd0, DEF_INITBUD});
            b_q         <= {32'd0, DEF_INITBUD};
            bmin_q      <= {32'd0, DEF_INITBUD};
            bmax_q      <= {32'd0, DEF_INITBUD};
            prev_main_q <= 64'd0;
            win_main_q  <= 64'd0;
            win_cnt_q   <= 64'd0;
            win_vdone_q <= 64'd0;
            win_allact_q<= 1'b0;
            nodone_run_q<= 64'd0;
            nodone_max_q<= 64'd0;
            m6_started_q<= 1'b0;
            m6_cd_q     <= 64'd0;

            for (int i = 0; i < NSTAT; i++) stat_q[i] <= {CounterWidth{1'b0}};
            for (int i = 0; i < NHIST; i++) hist_q[i] <= {CounterWidth{1'b0}};
        end else begin
            //-----------------------------------------------------------------
            // statistics (wrapped at CounterWidth, overflow is sticky)
            //-----------------------------------------------------------------
            for (int i = 0; i < NSTAT; i++)
                stat_q[i] <= do_clear ? {CounterWidth{1'b0}}
                                      : stat_sum[i][CounterWidth-1:0];
            for (int i = 0; i < NHIST; i++)
                hist_q[i] <= do_clear ? {CounterWidth{1'b0}}
                                      : hist_sum[i][CounterWidth-1:0];

            //-----------------------------------------------------------------
            // datapath (armed, not frozen)
            //-----------------------------------------------------------------
            if (win_run) begin
                balance_q <= bal_next;

                if (win_last) begin
                    win_cnt_q    <= 64'd0;
                    win_allact_q <= 1'b1;
                    win_vdone_q  <= 64'd0;
                end else begin
                    win_cnt_q    <= win_cnt_q + 64'd1;
                    win_allact_q <= act_all_now;
                    win_vdone_q  <= vdone_now;
                end

                // mode7 stale base rotation
                if (win_last) begin
                    prev_main_q <= win_main_q + main_inc;
                    win_main_q  <= 64'd0;
                end else begin
                    win_main_q  <= win_main_q + main_inc;
                end

                // adaptive feedback / b seen tracking
                if (win_complete && (mode_q != 32'd0) && (fb_inc || fb_dec)) begin
                    b_q <= b_next;
                    if (b_next < bmin_q) bmin_q <= b_next;
                    if (b_next > bmax_q) bmax_q <= b_next;
                end

                // mode6 gap countdown
                m6_cd_q <= m6_cd_next;
                if ((mode_q == 32'd6) && a_done_i && !m6_started_q)
                    m6_started_q <= 1'b1;
            end

            nodone_run_q <= nodone_run_q == 0 && !(win_run && v_active_i && !v_done_i)
                          ? (win_run && v_active_i && !v_done_i ? nodone_run_q + 64'd1 : 64'd0)
                          : nodone_run_next;
            nodone_max_q <= nodone_max_next;

            //-----------------------------------------------------------------
            // commands (win_run is deasserted whenever a command can fire)
            //-----------------------------------------------------------------
            if (do_arm) begin
                armed_q     <= 1'b1;
                aborted_q   <= 1'b0;
                frozen_q    <= 1'b0;
                balance_q   <= $signed(init_c);
                b_q         <= init_c;
                bmin_q      <= init_c;
                bmax_q      <= init_c;
                prev_main_q <= 64'd0;
                win_main_q  <= 64'd0;
                win_cnt_q   <= 64'd0;
                win_allact_q<= 1'b1;
                win_vdone_q <= 64'd0;
                m6_started_q<= 1'b0;
                m6_cd_q     <= 64'd0;
                nodone_run_q<= 64'd0;
            end

            if (do_abort)  aborted_q <= 1'b1;
            if (do_freeze) frozen_q  <= 1'b1;

            if (do_clear) begin
                armed_q     <= 1'b0;
                aborted_q   <= 1'b0;
                frozen_q    <= 1'b0;
                balance_q   <= $signed(init_c);
                b_q         <= init_c;
                bmin_q      <= init_c;
                bmax_q      <= init_c;
                prev_main_q <= 64'd0;
                win_main_q  <= 64'd0;
                win_cnt_q   <= 64'd0;
                win_allact_q<= 1'b0;
                win_vdone_q <= 64'd0;
                m6_started_q<= 1'b0;
                m6_cd_q     <= 64'd0;
                nodone_run_q<= 64'd0;
                nodone_max_q<= 64'd0;
            end

            //-----------------------------------------------------------------
            // configuration writes (rejected while armed)
            //-----------------------------------------------------------------
            if (cfg_wr && !armed_q) begin
                case (index_i[7:0])
                    R_MODE:     mode_q     <= wdata_i[31:0];
                    R_WINDOW:   window_q   <= wdata_i[31:0];
                    R_TARGET:   target_q   <= wdata_i[31:0];
                    R_DEADBAND: deadband_q <= wdata_i[31:0];
                    R_INITBUD:  initbud_q  <= wdata_i[31:0];
                    R_MINBUD:   minbud_q   <= wdata_i[31:0];
                    R_MAXBUD:   maxbud_q   <= wdata_i[31:0];
                    R_STEP:     step_q     <= wdata_i[31:0];
                    R_CAP:      cap_q      <= wdata_i[31:0];
                    R_WHIT:     whit_q     <= wdata_i[31:0];
                    R_WMISS:    wmiss_q    <= wdata_i[31:0];
                    R_WPTW:     wptw_q     <= wdata_i[31:0];
                    default: ;
                endcase
            end

            //-----------------------------------------------------------------
            // sticky errors: reset or a legal CLEAR are the only recovery
            //-----------------------------------------------------------------
            if (do_clear) err_q <= 64'd0;
            else          err_q <= err_q | new_err | err_add;
        end
    end

